(
    `product` LowCardinality(String),
    `tenant` LowCardinality(String),
    `qualification_group_id` Int32,
    `name` String,
    `display_name` String,
    `description` Nullable(String),
    `is_active` Bool,
    `created_on` DateTime64(3),
    `created_by` String,
    `last_modified_on` Nullable(DateTime64(3)),
    `last_modified_by` Nullable(String),
    `_version` UInt64,
    `_deleted` UInt8
)
AS SELECT
    _product AS product,
    _tenant AS tenant,
    Qualification_Group_ID AS qualification_group_id,
    Qualification_Group_Name AS name,
    Qualification_Group_Display_Name AS display_name,
    Qualification_Group_Description AS description,
    Is_Active AS is_active,
    Created_On AS created_on,
    Created_By AS created_by,
    Last_modified_on AS last_modified_on,
    Last_modified_by AS last_modified_by,
    _source_ts_ms AS _version,
    toUInt8(__deleted = 'true') AS _deleted
FROM raw.qualification_groups;
